// Generated offline by scripts/build-cloud-volume.mjs; no meshing during page load.
import { BufferGeometry, Float32BufferAttribute } from 'three';
const data='';
let decoded;
export function createCloudGeometry(){
 if(!decoded){const raw=atob(data), bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)), view=new DataView(bytes.buffer), count=3876;const positions=new Float32Array(count*3), normals=new Float32Array(count*3);for(let i=0;i<count*3;i++){positions[i]=view.getInt16(i*2,true)/32767*[.89,.32,.38][i%3];normals[i]=view.getInt16((count*3+i)*2,true)/32767;}decoded={positions,normals};}
 const geometry=new BufferGeometry();geometry.setAttribute('position',new Float32BufferAttribute(decoded.positions,3));geometry.setAttribute('normal',new Float32BufferAttribute(decoded.normals,3));return geometry;
}
